// ════════════════════════════════════════════════════════════════
// RIKIKI · scene capacity, how much a field holds
//
// The measured answer to "how long may this label, this note be": characters of
// plain text per field, by shape, canvas width and number of items. The numbers
// are in scene-capacity.data.ts, generated by `scripts/scene-bench/capacity.mjs`
// on the real fonts · this is only the reader.
//
// Conservative on purpose: the width is rounded DOWN to a width that was
// measured, the count UP to the next that was, so a text that "fits" here fits
// there. Plain words of six letters are what was measured · a text of wide
// letters (MMM) or of a long compound holds less, and the scene says so itself
// (`SCENE_TEXT_TOO_LONG`). This is the guide before drawing, not the proof after.
// ════════════════════════════════════════════════════════════════

import { CAPACITY_WIDTHS, SCENE_CAPACITY } from './scene-capacity.data.js';

/** The fields a shape wraps, as measured. */
export function capacityFields(kind: string): string[] {
  const byWidth = SCENE_CAPACITY[kind];
  const widest = byWidth?.[Math.max(...CAPACITY_WIDTHS)];
  const first = widest ? Object.values(widest)[0] : undefined;
  return first ? Object.keys(first) : [];
}

/** The widest measured width that is not wider than `width` · null under the narrowest. */
function measuredWidth(width: number): number | null {
  const under = CAPACITY_WIDTHS.filter((w) => w <= width);
  return under.length ? Math.max(...under) : null;
}

/** Characters a field takes in a scene of `kind` drawn `width` units wide with
 *  `count` items, or null when nothing was measured for it (an unknown shape or
 *  field). 0 means the field cannot hold even a word there, and under the
 *  narrowest measured width every field is 0. */
export function capacityOf(
  kind: string,
  width: number,
  count: number,
  field: string,
): number | null {
  const byCount = SCENE_CAPACITY[kind]?.[measuredWidth(width) ?? -1];
  if (!byCount && measuredWidth(width) === null && SCENE_CAPACITY[kind]) {
    return capacityFields(kind).includes(field) ? 0 : null;
  }
  if (!byCount) return null;
  const counts = Object.keys(byCount)
    .map(Number)
    .sort((a, b) => a - b);
  // Fewer items than measured holds at least what the fewest does · more holds what the most does.
  const at = counts.find((c) => c >= count) ?? counts[counts.length - 1];
  const fields = at === undefined ? undefined : byCount[at];
  return fields?.[field] ?? null;
}

/** Whether a text of `chars` characters is within what the field holds. */
export function fitsCapacity(
  kind: string,
  width: number,
  count: number,
  field: string,
  chars: number,
): boolean | null {
  const holds = capacityOf(kind, width, count, field);
  return holds === null ? null : chars <= holds;
}
